///|
fn diagnostic_previous_loss(source : Json) -> Json {
  let event = diagnostic_recording_event("degraded", "previous_run_unflushed")
  set_field(event, "missingRange", Json::string("unknown"))
  if field(source, "affectedRunId") != Some(Json::string("unknown")) &&
    field(source, "runId") is Some(Json::String(id)) &&
    id.length() > 0 &&
    id.length() <= 80 &&
    id.iter().all(c => (c >= '0' && c <= '9') || c == '_') {
    set_field(event, "runId", Json::string(id))
  } else {
    set_field(event, "affectedRunId", Json::string("unknown"))
  }
  for name in ["missingFromTime", "missingThroughTime"] {
    if field(source, name) is Some(Json::String(value)) &&
      value.length() > 0 &&
      value.length() <= 25 &&
      value.iter().all(c => c >= '0' && c <= '9') {
      set_field(event, name, Json::string(value))
    }
  }
  if field(event, "missingFromTime") is Some(_) &&
    field(event, "missingThroughTime") is Some(_) {
    set_field(event, "missingRange", Json::string("observed"))
  }
  let reason = field(source, "previousReason").unwrap_or(
    field(source, "reason").unwrap_or(Json::null()),
  )
  if reason is Json::String(value) &&
    [
      "lock_busy", "invalid_lock", "invalid_store", "store_timeout", "store_unavailable",
      "buffer_full", "protected_values_unavailable", "workspace_recording_unknown",
    ].contains(value) {
    set_field(event, "previousReason", reason)
  }
  event
}

///|
async fn recover_diagnostic_health(directory : String) -> Unit {
  if @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") == Some("0") {
    return
  }
  let path = directory + "/diagnostic-health.json"
  if !@fs.exists(path) {
    return
  }
  let previous = @async.with_timeout(20, async fn() {
    guard @fs.kind(path, follow_symlink=false) == @fs.FileKind::Regular &&
      @fs.file_size(path) <= 65536L else {
      return Json::null()
    }
    @json.parse(@fs.read_file(path).text())
  }) catch {
    error =>
      if @async.is_being_cancelled() {
        raise error
      } else {
        Json::null()
      }
  }
  if field(previous, "priorLoss") is Some(Json::Array(losses)) {
    for loss in losses {
      if diagnostic_previous_losses.length() >= 31 {
        break
      }
      diagnostic_previous_losses.push(diagnostic_previous_loss(loss))
    }
    if losses.length() > 31 {
      diagnostic_previous_losses.push(diagnostic_previous_loss(Json::null()))
    }
  }
  diagnostic_previous_losses.push(diagnostic_previous_loss(previous))
  for event in diagnostic_previous_losses {
    diagnostic_pending.push({ event, failed: true, time: @env.now(), })
  }
  diagnostic_recording_health.incident = true
  diagnostic_recording_health.reason = "previous_run_unflushed"
  diagnostic_recording_health.phase = "recovery"
}

///|
fn diagnostic_json(
  value : Json,
  environment : Map[String, String],
  protected_secrets : Array[String],
  truncated : Ref[Bool],
  depth : Int32,
  stable_activity~ : Bool = false,
  secret_states~ : Bool = false,
  stable_operation~ : Bool = false,
  stable_arguments~ : Bool = false,
  parent~ : String = "",
) -> Json {
  if depth >= 64 {
    truncated.val = true
