///|
fn diagnostic_add_protected(
  value : String,
  output : String,
  uncertain : Bool,
  destination : Array[String],
  result : DiagnosticProtectedValues,
) -> Unit {
  if value == "" ||
    (
      !output.contains(value) &&
      (!uncertain || diagnostic_partial_secret(output, [value]) == output)
    ) {
    return
  }
  if result.secrets.length() >= 512 {
    result.incomplete = true
    return
  }
  destination.push(value)
}

///|
fn diagnostic_protected_values(
  value : Json,
  result : DiagnosticProtectedValues,
  output : String,
  uncertain : Bool,
  secret~ : Bool = false,
  depth~ : Int32 = 0,
) -> Unit {
  if result.visited >= 65536 || depth >= 64 {
    result.incomplete = true
    return
  }
  result.visited += 1
  match value {
    Json::String(text) if text != "" && secret => {
      let destination = result.secrets
      diagnostic_add_protected(text, output, uncertain, destination, result)
      for line in text.split("\n") {
        if line != "" && line.length() < text.length() {
          diagnostic_add_protected(
            line.to_owned(),
            output,
            uncertain,
            destination,
            result,
          )
        }
        for word in line.split(" ") {
          for part in word.split("=") {
            if part != "" && part.length() < text.length() {
              diagnostic_add_protected(
                part.to_owned(),
                output,
                uncertain,
                destination,
                result,
              )
            }
          }
        }
      }
      let escaped = Json::string(text).stringify()
      if escaped.length() > 2 {
        let encoded = escaped[1:escaped.length() - 1].to_owned()
        if encoded != text {
          diagnostic_add_protected(
            encoded, output, uncertain, destination, result,
          )
        }
      }
    }
    Json::String(text) if text != "" => {
      let mut next_secret = false
      for word in text.split(" ") {
        let word = word.to_owned()
        if next_secret {
          diagnostic_add_protected(
            word,
            output,
            uncertain,
            result.secrets,
            result,
          )
          next_secret = false
        } else if word.split_once("=") is Some((name, value)) {
          if credential_field(name.to_owned(), for_diagnostics=true) {
            diagnostic_add_protected(
              value.to_owned(),
              output,
              uncertain,
              result.secrets,
              result,
            )
          }
        } else if word.has_prefix("-") &&
          credential_field(word, for_diagnostics=true) {
          next_secret = true
        }
      }
    }
    Json::Array(values) =>
      for item in values {
        diagnostic_protected_values(
          item,
          result,
          output,
          uncertain,
          secret~,
          depth=depth + 1,
        )
      }
    Json::Object(values) =>
      for name, item in values {
        let key = name.to_lower().replace_all(old="_", new="")
        diagnostic_protected_values(
          item,
          result,
          output,
          uncertain,
          secret=secret ||
            credential_field(name, for_diagnostics=true) ||
            key == "pairingcode",
          depth=depth + 1,
        )
      }
    _ => ()
  }
}

///|
fn diagnostic_output(
  output : Bytes,
  environment : Map[String, String],
  protected_input? : String,
  protect_all_input~ : Bool = false,
  protected_secrets? : Array[String],
  omitted~ : Bool = false,
) -> String? {
  if output.length() == 0 {
    return if omitted {
      Some("[error details incomplete or truncated]")
    } else {
      None
    }
  }
  let limit = if output.length() > 8192 { 8192 } else { output.length() }
  let incomplete = omitted || limit < output.length()
  let text = @utf8.decode_lossy(output[:limit])
  let safeguards : DiagnosticProtectedValues = {
    secrets: [],
    visited: 0,
    incomplete: false,
  }
  if protected_input is Some(input) {
    diagnostic_protected_values(
      @json.parse(input),
      safeguards,
      text,
      incomplete,
      secret=protect_all_input,
    ) catch {
      _ => safeguards.incomplete = true
    }
  }
  if safeguards.incomplete {
    return Some(
      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
    )
  }
  Some(
    diagnostic_text(
      text,
      environment~,
      omitted=incomplete,
      protected_secrets=safeguards.secrets + protected_secrets.unwrap_or([]),
      incomplete_final_line=incomplete && output[limit - 1] != b'\n',
    ),
  )
}

