async fn save_diagnostic(
  stage : String,
  status : String,
  exit_code? : Int32,
  error_type? : String,
  phase? : String,
  duration_ms? : Double,
  attempt? : Int32,
  retry_delay_ms? : Int32,
  timeout_ms? : Int32,
  os_errno? : Int32,
  source? : CreateEvidence,
  error_message? : String,
  details_truncated~ : Bool = false,
  tunnel_directory? : String,
  expected_workspace_uid? : String,
  observed_workspace_uid? : String,
  evidence? : Json,
  evidence_incomplete~ : Bool = false,
  evidence_stable_activity~ : Bool = false,
  evidence_stable_operation~ : Bool = false,
  run_completeness? : String,
  recording? : Bool,
  environment? : Map[String, String],
  protected_secrets? : Array[String],
) -> Unit {
  if !recording.unwrap_or(
      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
    ) {
    return
  }
  diagnostic_run_has_events.val = true
  let event_time = @env.now()
  let event : Json = {
    "stage": stage,
    "status": status,
    "time": event_time.to_string(),
    "runId": recording_run_id,
    "adapterVersion": version,
  }
  if create_recording.attempt > 0 {
    set_field(
      event,
      "createAttempt",
      Json::number(create_recording.attempt.to_double()),
    )
    set_field(event, "createPhase", Json::string(create_recording.phase))
  }
  let process_environment = @env.get_env_vars()
  let secrets = [] + protected_secrets.unwrap_or([])
  if environment is Some(environment) {
    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
      secrets.push(secret)
    }
  }
  if tunnel_directory is Some(directory) &&
    diagnostic_workspace_environments.get(directory) is Some(environment) {
    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
      secrets.push(secret)
    }
  }
  if error_message is Some(message) {
    let message = diagnostic_text(
      message,
      environment=process_environment,
      protected_secrets=secrets,
    )
    set_field(event, "errorMessage", Json::string(message))
    set_field(
      event,
      "detailsTruncated",
      Json::boolean(
        details_truncated ||
        message == "[error details incomplete or truncated]" ||
        message.has_suffix("\n[error details incomplete or truncated]"),
      ),
    )
  }
  if tunnel_directory is Some(directory) {
    set_field(
      event,
      "tunnelDirectory",
      Json::string(
        diagnostic_text(
          directory,
          environment=process_environment,
          protected_secrets=secrets,
        ),
      ),
    )
  }
  for
    pair in [
      ("expectedWorkspaceUid", expected_workspace_uid),
      ("observedWorkspaceUid", observed_workspace_uid),
    ] {
    if pair.1 is Some(value) {
      set_field(
        event,
        pair.0,
        Json::string(
          diagnostic_text(
            value,
            environment=process_environment,
            protected_secrets=secrets,
          ),
        ),
      )
    }
  }
  let evidence_truncated : Ref[Bool] = { val: evidence_incomplete, }
  if source is Some(evidence) {
    let value = evidence.to_json()
    if value.stringify().length() <= 65536 {
      set_field(
        event,
        "source",
        diagnostic_json(
          value,
          process_environment,
          secrets,
          evidence_truncated,
          0,
          stable_activity=evidence_stable_activity,
        ),
      )
    } else {
      evidence_truncated.val = true
    }
  }
  if evidence is Some(value) {
    if value.stringify().length() <= 65536 {
      set_field(
        event,
        "evidence",
        diagnostic_json(
          value,
          process_environment,
          secrets,
          evidence_truncated,
          0,
          stable_activity=evidence_stable_activity,
          secret_states=stage == "server-environment",
          stable_operation=evidence_stable_operation,
          stable_arguments=[
            "create-arguments", "create-options", "resolve-context",
          ].contains(stage),
        ),
      )
    } else {
      evidence_truncated.val = true
    }
  }
  if evidence_truncated.val {
    set_field(event, "evidenceTruncated", Json::boolean(true))
    set_field(event, "completeness", Json::string("partial"))
  }
  if details_truncated ||
    evidence_truncated.val ||
    (
      error_message is Some(message) &&
      message.contains("[error details incomplete or truncated]")
    ) {
    diagnostic_recording_health.run_partial = true
  }
  if run_completeness is Some(value) {
    set_field(event, "runCompleteness", Json::string(value))
  }
  if os_errno is Some(code) && code > 0 && code < 4096 {
    set_field(event, "osErrno", Json::number(code.to_double()))
  }
  if exit_code is Some(code) {
    set_field(event, "exitCode", Json::number(code.to_double()))
  }
  for pair in [("errorType", error_type), ("phase", phase)] {
    if pair.1 is Some(text) {
      set_field(event, pair.0, Json::string(text))
    }
  }
  if duration_ms is Some(value) {
    set_field(event, "durationMs", Json::number(value))
  }
  if attempt is Some(value) {
    set_field(event, "attempt", Json::number(value.to_double()))
  }
  if timeout_ms is Some(value) {
    set_field(event, "timeoutMs", Json::number(value.to_double()))
  }
  if retry_delay_ms is Some(value) {
    set_field(event, "retryDelayMs", Json::number(value.to_double()))
  }
  let failed = error_type is Some(_) ||
    ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
      status,
    )
  if diagnostic_pending.length() >= 64 {
    let mut evict = -1
    if failed {
      for index in diagnostic_pending_inflight.val..<diagnostic_pending.length() {
        if !diagnostic_pending[index].failed {
          evict = index
          break
        }
      }
      if evict < 0 &&
        diagnostic_pending_inflight.val < diagnostic_pending.length() {
        evict = diagnostic_pending_inflight.val
      }
    }
    if evict < 0 {
      diagnostic_recording_failed("buffer_full", phase="buffer", event_time~)
      return
    }
    let removed = diagnostic_pending.remove(evict)
    diagnostic_pending.push({ event, failed, time: event_time, })
    diagnostic_recording_failed(
      "buffer_full",
      phase="buffer",
      event_time=removed.time,
    )
    try_flush_diagnostic_recording()
    return
  }
  diagnostic_pending.push({ event, failed, time: event_time, })
  try_flush_diagnostic_recording()
}

