///|
fn Progress::remember(
  self : Progress,
  message : String,
  warning~ : Bool,
) -> Unit {
  let lines = if warning { self.failures } else { self.recent }
  if lines.last() == Some(message) {
    return
  }
  if lines.length() == 8 {
    ignore(lines.remove(0))
    self.details_truncated = true
  }
  lines.push(message)
}

///|
fn Progress::failure_detail(self : Progress) -> String {
  let lines = self.failures +
    self.recent.filter(line => !self.failures.contains(line))
  let detail = if lines.is_empty() {
    "no readable error message from subprocess"
  } else {
    lines.join("\n")
  }
  detail +
  (if self.details_truncated {
    "\n[error details incomplete or truncated]"
  } else {
    ""
  })
}

///|
fn Progress::remember_unrecognized(self : Progress, text : String) -> Unit {
  if self.protection_incomplete {
    self.details_truncated = true
    let unavailable = "error detail unavailable because workspace protection values could not be read"
    if !self.unrecognized.contains(unavailable) {
      self.unrecognized.push(unavailable)
    }
    return
  }
  guard self.safe_message(text) is Some(safe) else {
    self.details_truncated = true
    return
  }
  if self.unrecognized.length() == 8 {
    ignore(self.unrecognized.remove(0))
    self.details_truncated = true
  }
  self.unrecognized.push(safe)
}

///|
fn Progress::remember_unrecognized_json(self : Progress, event : Json) -> Unit {
  if self.protection_incomplete {
    self.remember_unrecognized("")
    return
  }
  let truncated : Ref[Bool] = { val: false, }
  let safe = diagnostic_json(event, {}, self.secrets, truncated, 0).stringify()
  if truncated.val {
    self.details_truncated = true
  }
  self.remember_unrecognized(safe)
}

///|
async fn Progress::status(self : Progress, event : Json) -> Unit {
  guard field(event, "phase") is Some(Json::String(phase)) &&
    phase_label(phase) is Some(label) &&
    field(event, "state") is Some(Json::String(state)) &&
    ["started", "succeeded", "failed", "skipped"].contains(state) else {
    return
  }
  if self.phase_count < 128 {
    self.phase_count += 1
    save_diagnostic(
      self.stage,
      state,
      phase~,
      error_type?=if state == "failed" { Some("backend_phase") } else { None },
      evidence?=self.context,
      evidence_stable_operation=true,
      protected_secrets=self.secrets,
      recording=self.recording,
    )
  } else if self.phase_count == 128 {
    self.phase_count += 1
    self.details_truncated = true
    save_diagnostic(
      self.stage,
      "diagnostics-truncated",
      error_type="phase_limit",
      phase~,
      evidence?=self.context,
      evidence_incomplete=true,
      evidence_stable_operation=true,
      protected_secrets=self.secrets,
      recording=self.recording,
    )
  }
  let key = ["pipeline", "operationId", "phase", "step"]
    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
    .join(":")
  if state == "started" {
    if self.operations.length() >= 256 {
      self.operations.clear()
    }
    self.operations.set(key, @env.now())
    progress_message(label + ": running…")
  } else {
    let duration = match field(event, "durationMs") {
      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
        Some(seconds(value.to_uint64()))
      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
    }
    self.operations.remove(key)
    let timing = duration.map(value => value + ", ").unwrap_or("") +
      "elapsed " +
      seconds(@env.now() - progress_started)
    progress_message(
      label +
      ": " +
      (if state == "succeeded" { "done" } else { state }) +
      " (" +
      timing +
      ")",
    )
  }
}

///|
fn classic_build_step(text : String) -> Bool {
  guard text.has_prefix("Step ") &&
    text[5:].split_once("/") is Some((step, rest)) &&
    rest.split_once(" ") is Some((total, detail)) else {
    return false
  }
  step.length() > 0 &&
  total.length() > 0 &&
  step.iter().all(c => c >= '0' && c <= '9') &&
  total.iter().all(c => c >= '0' && c <= '9') &&
  detail.trim().has_prefix(":")
}

///|
async fn Progress::message(
  self : Progress,
  text : String,
  debug~ : Bool,
  warning~ : Bool,
  emit~ : Bool = true,
) -> Unit {
  if self.protection_incomplete {
    self.details_truncated = true
    self.remember(
      "error detail unavailable because workspace protection values could not be read",
      warning=true,
    )
    return
  }
  for line in text.split("\n") {
    let text = line.trim().to_owned()
    if text == "" {
      continue
    }
    guard self.safe_message(text) is Some(safe) else {
      self.details_truncated = true
      continue
    }
    if !debug || warning {
      self.remember(safe, warning~)
    }
    if !emit {
      continue
    }
    if safe.has_prefix("#") {
      guard safe.split_once(" ") is Some((id, rest)) &&
        id.length() > 1 &&
        id[1:].iter().all(c => c >= '0' && c <= '9') else {
        continue
      }
      let detail = rest.trim().to_owned()
      guard detail.has_prefix("[") ||
        detail.has_prefix("DONE") ||
        detail.has_prefix("ERROR") ||
        detail.has_prefix("CACHED") else {
        continue
      }
      if detail.has_prefix("ERROR") && debug && !warning {
        self.remember(safe, warning=true)
      }
      if self.builds.get(id.to_owned()) == Some(detail) {
        continue
      }
      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
        self.builds.set(id.to_owned(), detail)
      }
      progress_message("Build " + id.to_owned() + ": " + detail)
    } else if classic_build_step(safe) {
      // Classic RUN output has no prefix. Only its own completion marker
      // ends this mode; phase events on another pipe can arrive ahead of it.
      self.classic_build = true
      progress_message("Build " + safe)
    } else if safe.has_prefix("Successfully built ") ||
      safe.has_prefix("Successfully tagged ") {
      self.classic_build = false
      progress_message("Build: " + safe)
    } else if self.classic_build && !warning {
      continue
    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
      progress_message(self.stage + ": " + safe)
    } else if !debug && safe.has_prefix("[credential") {
      progress_message(self.stage + ": " + safe)
    }
  }
}

///|
fn Progress::learn_event(self : Progress, event : Json, line : String) -> Unit {
  if event != Json::null() {
    let protected_values : DiagnosticProtectedValues = {
      secrets: [],
      visited: 0,
      incomplete: false,
    }
    diagnostic_protected_values(event, protected_values, line, false)
    if protected_values.incomplete ||
      self.secrets.length() + protected_values.secrets.length() > 1024 {
      self.protection_incomplete = true
      self.details_truncated = true
      self.recent.clear()
      self.failures.clear()
      self.unrecognized.clear()
    } else {
      for secret in protected_values.secrets {
        add_protected_secret(self.secrets, secret)
      }
      self.secrets.sort_by((a, b) => b.length().compare(a.length()))
    }
  }
}

///|
fn progress_json_text(text : String, truncated : Ref[Bool]) -> String {
  if !text.contains("\u001b") {
    return text
  }
  let parts : Array[String] = []
  for line in text.split("\n") {
    match terminal_text(line.to_owned()) {
      Some(safe) => parts.push(safe)
      None => {
        truncated.val = true
        return "[unavailable]"
      }
    }
  }
  parts.join("\n")
}

///|
fn progress_normalize_json(
  value : Json,
  truncated : Ref[Bool],
  depth : Int32,
) -> Json {
  if depth >= 64 {
    truncated.val = true
    return Json::string("[unavailable]")
  }
  match value {
    Json::String(text) => Json::string(progress_json_text(text, truncated))
    Json::Array(values) =>
      Json::array(
        values.map(item => progress_normalize_json(item, truncated, depth + 1)),
      )
    Json::Object(values) => {
      let result = Json::empty_object()
      for name, item in values {
        let key = progress_json_text(name, truncated)
        if field(result, key) is Some(_) {
          truncated.val = true
        } else {
          set_field(
            result,
            key,
            progress_normalize_json(item, truncated, depth + 1),
          )
        }
      }
      result
    }
    _ => value
  }
}

///|
fn Progress::filter_output_line(
  self : Progress,
  line : String,
  private_key : Ref[Bool],
  blocked : Ref[Bool],
) -> String? {
  if blocked.val {
    return None
  }
  let event = @json.parse(line) catch { _ => Json::null() }
  self.learn_event(event, line)
  let normalized = if event != Json::null() {
    let truncated : Ref[Bool] = { val: false, }
    let value = progress_normalize_json(event, truncated, 0)
    if truncated.val {
      self.details_truncated = true
      blocked.val = true
      return None
    }
    value.stringify()
  } else {
    match terminal_text(line) {
      Some(text) => text
      None => {
        self.details_truncated = true
        blocked.val = true
        return None
      }
    }
  }
  let truncated : Ref[Bool] = { val: false, }
  let safe = mask_private_key(normalized, private_key, truncated)
  if truncated.val {
    self.details_truncated = true
  }
  safe
}

///|

///|
async fn Progress::line(
  self : Progress,
  line : String,
  statuses~ : Bool,
  messages~ : Bool,
) -> Unit {
  if line.trim() == "" {
    return
  }
  let event = @json.parse(line) catch { _ => Json::null() }
  if field(event, "kind") == Some(Json::string("status")) {
    if field(event, "state") == Some(Json::string("failed")) &&
      field(event, "error") is Some(error) {
      for name in ["message", "hint"] {
        if field(error, name) is Some(Json::String(text)) {
          self.message(
            text,
            debug=false,
            warning=true,
            emit=messages || statuses,
          )
        }
      }
      self.remember_unrecognized_json(event)
    }
    if statuses || messages {
      self.status(event)
    }
    return
  }
  // Result envelopes and arbitrary structured responses are never log text.
  if field(event, "kind") == Some(Json::string("result")) {
    if field(event, "outcome") != Some(Json::string("success")) &&
      (
        field(event, "error") is Some(_) ||
        field(event, "message") is Some(_) ||
        field(event, "code") is Some(_) ||
        field(event, "outcome") == Some(Json::string("failure")) ||
        field(event, "outcome") == Some(Json::string("error"))
      ) {
      self.remember_unrecognized_json(event)
    }
    return
  }
  if field(event, "kind") == Some(Json::string("orca-env-devsy-server-exit")) {
    return
  }
  if event is Json::Object(_) {
    let kind = field(event, "kind")
    guard kind == None ||
      kind == Some(Json::string("log")) ||
      kind == Some(Json::string("error")) else {
      self.remember_unrecognized_json(event)
      return
    }
    let message = match field(event, "msg") {
      Some(value) => Some(value)
      None =>
        match field(event, "message") {
          Some(value) => Some(value)
          None =>
            match field(event, "error") {
              Some(Json::Object(_) as value) => field(value, "message")
              value => value
            }
        }
    }
    guard message is Some(Json::String(text)) else {
      self.remember_unrecognized_json(event)
      return
    }
    let level = field(event, "level")
    self.message(
      text,
      debug=level == Some(Json::string("debug")) ||
        level == Some(Json::string("trace")),
      warning=kind == Some(Json::string("error")) ||
        level == Some(Json::string("warn")) ||
        level == Some(Json::string("error")),
      emit=messages || (statuses && kind != None),
    )
  } else {
    if event != Json::null() {
      self.remember_unrecognized_json(event)
      return
    }
    // Malformed JSON and binary output are not a safe free-text fallback.
    let text = line.trim().to_owned()
    if text.has_prefix("[ERROR]") || text.has_prefix("[WARN]") {
      self.message(text, debug=false, warning=true, emit=messages)
      return
    }
    if text.has_prefix("{") || text.has_prefix("[") {
      self.details_truncated = true
      self.remember_unrecognized(text)
      return
    }
    self.message(
      text,
      debug=text.contains(" DEBUG ") ||
        text.contains(" TRACE ") ||
        text.has_prefix("DEBUG ") ||
        text.has_prefix("TRACE "),
      warning=text.contains(" WARN ") ||
        text.contains(" ERROR ") ||
        text.has_prefix("WARN ") ||
        text.has_prefix("ERROR "),
      emit=messages,
    )
  }
}

///|
async fn Progress::stderr_line(
  self : Progress,
  line : String,
  statuses~ : Bool,
  messages~ : Bool,
) -> Unit {
  let event = @json.parse(line) catch { _ => Json::null() }
  if event != Json::null() {
    self.line(line, statuses~, messages~)
    let truncated : Ref[Bool] = { val: false, }
    let safe = diagnostic_json(event, {}, self.secrets, truncated, 0).stringify()
    if truncated.val {
      self.details_truncated = true
    }
    self.message(safe, debug=false, warning=true, emit=false)
    return
  } else if event == Json::null() &&
    (line.trim().has_prefix("[") || line.trim().has_prefix("{")) {
    self.details_truncated = true
    self.message(line, debug=false, warning=true, emit=false)
    return
  }
  self.line(line, statuses~, messages~)
}

///|
async fn Progress::read_output(
  self : Progress,
  reader : @process.ReadFromProcess,
  capture~ : Bool,
  statuses~ : Bool = false,
  messages~ : Bool = false,
  raw_messages~ : Bool = false,
) -> String {
  let output = @buffer.Buffer(size_hint=4096)
  let pending = @buffer.Buffer(size_hint=4096)
  let private_key : Ref[Bool] = { val: false, }
  let blocked : Ref[Bool] = { val: false, }
  let mut oversized = false
  let mut tail = ""
  while reader.read_some(max_len=4096) is Some(chunk) {
    if capture {
      output.write_bytes(chunk)
    } else {
      tail += @utf8.decode_lossy(chunk)
      if tail.length() > 8192 {
        tail = tail[tail.length() - 8192:].to_owned()
      }
    }
    for byte in chunk {
      if byte == b'\n' || byte == b'\r' {
        if !oversized && pending.length() > 0 {
          let line = @utf8.decode(pending.to_bytes()) catch {
            _ => {
              self.details_truncated = true
              blocked.val = true
              ""
            }
          }
          if self.filter_output_line(line, private_key, blocked) is Some(safe) {
            if raw_messages {
              self.message(safe, debug=false, warning=true, emit=false)
            } else if capture {
              self.line(safe, statuses~, messages~)
            } else {
              self.stderr_line(safe, statuses~, messages~)
            }
          }
        }
        pending.reset()
        oversized = false
      } else if !oversized {
        if pending.length() == 65536 {
          pending.reset()
          oversized = true
          blocked.val = true
          self.details_truncated = true
        } else {
          pending.write_byte(byte)
        }
      }
    }
  }
  if !oversized && pending.length() > 0 {
    let line = @utf8.decode(pending.to_bytes()) catch {
      _ => {
        self.details_truncated = true
        blocked.val = true
        ""
      }
    }
    let masked = diagnostic_partial_secret(line, self.secrets)
    if masked != line {
      self.details_truncated = true
    }
    if self.filter_output_line(masked, private_key, blocked) is Some(safe) {
      if raw_messages {
        self.message(safe, debug=false, warning=true, emit=false)
      } else if capture {
        self.line(safe, statuses~, messages~)
      } else {
        self.stderr_line(safe, statuses~, messages~)
      }
    }
  }
  if capture {
    @utf8.decode(output.to_bytes())
  } else {
    tail
  }
}

///|
let progress_started : UInt64 = @env.now()

///|
fn seconds(milliseconds : UInt64) -> String {
  let tenths = milliseconds / 100UL
  "\{tenths / 10UL}.\{tenths % 10UL}s"
}

///|
fn progress_timing(started : UInt64) -> String {
  let now = @env.now()
  seconds(now - started) + ", elapsed " + seconds(now - progress_started)
}

///|
priv struct ProgressSink {
  lock : @async.Mutex
  mut available : Bool
}

///|
let progress_sink : ProgressSink = {
  lock: @async.Mutex::Mutex(),
  available: true,
}

///|
async fn progress_write(message : String) -> Unit {
  progress_sink.lock.acquire()
  defer progress_sink.lock.release()
  if !progress_sink.available {
    return
  }
  @stdio.stderr.write(message) catch {
    _ => {
      progress_sink.available = false
      save_diagnostic("progress-output", "failed", error_type="progress_io")
    }
  }
}

///|
async fn progress_message(message : String) -> Unit {
  let clock = @env.now() / 1000UL % 86400UL
  let pad = fn(value : UInt64) {
    if value < 10UL {
      "0" + value.to_string()
    } else {
      value.to_string()
    }
  }
  progress_write(
    pad(clock / 3600UL) +
    ":" +
    pad(clock / 60UL % 60UL) +
    ":" +
    pad(clock % 60UL) +
    " " +
    message +
    "\n",
  )
}

///|
fn devsy_progress_stage(stage : String) -> Bool {
  [
    "workspace-create", "workspace-create-full", "workspace-resume", "workspace-stop",
    "workspace-delete", "create-cleanup",
  ].contains(stage)
}

///|
fn phase_label(phase : String) -> String? {
  match phase {
    "cloning_repository" => Some("Clone repository")
    "resolving_config" => Some("Resolve devcontainer config")
    "initialize_command" => Some("Initialize")
    "preparing_devcontainer" => Some("Prepare devcontainer")
    "building_image" => Some("Build image")
    "starting_container" => Some("Start container")
    "injecting_agent" => Some("Install Devsy agent")
    "running_lifecycle_hook" => Some("Run lifecycle hooks")
    "waiting_for" => Some("Wait for container")
    "running_command" => Some("Run command")
    "configuring_workspace" => Some("Configure workspace")
    "configuring_ssh" => Some("Configure SSH")
    "starting_ssh_tunnel" => Some("Start SSH tunnel")
    "launching_ide" => Some("Prepare IDE")
    "stopping_workspace" => Some("Stop workspace")
    "deleting_workspace" => Some("Delete workspace")
    "rebuilding_workspace" => Some("Rebuild workspace")
    "resetting_workspace" => Some("Reset workspace")
    "importing_workspace" => Some("Import workspace")
    "ready" => Some("Workspace ready")
    "failed" => Some("Workspace failed")
    "installing_provider" => Some("Install provider")
    "resolving_options" => Some("Resolve provider options")
    "running_init" => Some("Initialize provider")
    _ => None
  }
}

///|
priv struct Progress {
  stage : String
  operations : Map[String, UInt64]
  builds : Map[String, String]
  secrets : Array[String]
  mut protection_incomplete : Bool
  recording : Bool
  context : Json?
  mut phase_count : Int32
  mut private_key : Bool
  mut classic_build : Bool
  recent : Array[String]
  failures : Array[String]
  unrecognized : Array[String]
  mut details_truncated : Bool
}

///|
fn sensitive_name(name : String) -> Bool {
  let normalized = name.to_lower().replace_all(old="-", new="_")
  if ["_enabled", "_disabled", "_count", "_mode", "_method"]
    .iter()
    .any(suffix => normalized.has_suffix(suffix)) {
    return false
  }
  let credential = credential_field(name, for_diagnostics=true)
  let name = name.to_lower()
  credential ||
  [
    "password", "passwd", "passphrase", "token", "secret", "api_key", "apikey", "auth",
    "credential", "private_key", "access_key", "storage_key", "cookie", "fnox_age_key",
  ]
  .iter()
  .any(marker => name.contains(marker))
}

///|
fn add_protected_secret(secrets : Array[String], value : String) -> Unit {
  if value == "" {
    return
  }
  let values = [value]
  for part in value.split("\n") {
    if part.trim() != "" && part.length() < value.length() {
      values.push(part.to_owned())
    }
  }
  for item in values {
    if !secrets.contains(item) {
      secrets.push(item)
    }
    let encoded = Json::string(item).stringify()
    let escaped = encoded[1:encoded.length() - 1].to_owned()
    if escaped != item && !secrets.contains(escaped) {
      secrets.push(escaped)
    }
  }
}

///|
fn Progress::new(
  stage : String,
  environment? : Map[String, String],
  recording_override? : Bool,
  context? : Json,
  protected_secrets? : Array[String],
  protection_incomplete~ : Bool = false,
) -> Progress {
  let secrets = []
  for name, value in environment.unwrap_or(@env.get_env_vars()) {
    if sensitive_name(name) && value != "" {
      // Multiline credentials must also be masked in line-oriented output.
      add_protected_secret(secrets, value)
    }
  }
  if protected_secrets is Some(values) {
    for value in values {
      add_protected_secret(secrets, value)
    }
  }
  secrets.sort_by((a, b) => b.length().compare(a.length()))
  {
    stage,
    operations: {},
    builds: {},
    secrets,
    protection_incomplete,
    recording: recording_override.unwrap_or(
      environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
      Some("0"),
    ),
    context,
    phase_count: 0,
    private_key: false,
    classic_build: false,
    recent: [],
    failures: [],
    unrecognized: [],
    details_truncated: false,
  }
}

///|
fn terminal_text(text : String) -> String? {
  let output = @buffer.Buffer(size_hint=256)
  let mut state = 0
  for c in text.iter() {
    match state {
      0 =>
        if c == '\u001b' {
          state = 1
        } else if c.to_int() < 32 && c != '\t' {
          return None
        } else {
          output.write_char_utf8(c)
        }
      1 =>
        if c == '[' {
          state = 2
        } else if c == ']' {
          state = 3
        } else {
          return None
        }
