///|
fn ascii_match_at(
  chars : Array[Char],
  offset : Int32,
  pattern : Array[Char],
) -> Bool {
  if offset + pattern.length() > chars.length() {
    return false
  }
  for index in 0..<pattern.length() {
    let value = chars[offset + index]
    let lower = if value >= 'A' && value <= 'Z' {
      (value.to_int() + 32).unsafe_to_char()
    } else {
      value
    }
    if lower != pattern[index] {
      return false
    }
  }
  true
}

///|
fn private_key_marker(
  chars : Array[Char],
  start : Int32,
  opening : Bool,
) -> (Int32, Int32)? {
  let prefix = (if opening { "-----begin " } else { "-----end " })
    .iter()
    .to_array()
  let ending = "private key-----".iter().to_array()
  for index in start..<chars.length() {
    if ascii_match_at(chars, index, prefix) {
      for end in (index + prefix.length())..<chars.length() {
        if ascii_match_at(chars, end, ending) {
          return Some((index, end + ending.length()))
        }
      }
      return None
    }
  }
  None
}

///|
fn mask_private_key(
  text : String,
  private_key : Ref[Bool],
  truncated : Ref[Bool],
) -> String? {
  let chars = text.iter().to_array()
  if chars.is_empty() {
    return Some("")
  }
  let output = @buffer.Buffer(size_hint=text.length())
  let mut position = 0
  while position < chars.length() {
    if private_key.val {
      if private_key_marker(chars, position, false) is Some((_, end)) {
        private_key.val = false
        position = end
      } else {
        truncated.val = true
        position = chars.length()
      }
    } else if private_key_marker(chars, position, true) is Some((start, end)) {
      output.write_string_utf8(character_text(chars, position, start))
      output.write_string_utf8("[private key redacted]")
      private_key.val = true
      position = end
      if private_key_marker(chars, position, false) is None {
        truncated.val = true
      }
    } else {
      output.write_string_utf8(character_text(chars, position, chars.length()))
      position = chars.length()
    }
  }
  if output.length() == 0 {
    return None
  }
  Some(@utf8.decode_lossy(output.to_bytes()))
}

