    set_field(result, "activity", field(evidence, "activity").unwrap())
    let evidence_incomplete : Ref[Bool] = { val: false, }
    let safe_evidence = if status != "Running" ||
      options.force ||
      mode == "resume" {
      evidence
    } else {
      match
        saved_workspace_secrets(
          state,
          for_output=true,
          include_pairing=activity_pairing.val is None,
        ) {
        Some(values) => {
          if activity_pairing.val is Some(pairing) && pairing != "" {
            add_protected_secret(values, pairing)
          }
          diagnostic_json(
            evidence,
            workspace_environment(state),
            values,
            evidence_incomplete,
            0,
            stable_activity=true,
          )
        }
        None => {
          evidence_incomplete.val = true
          (
            {
              "activity": field(evidence, "activity").unwrap(),
              "reason": "activity details unavailable",
              "detailsTruncated": true,
            } : Json)
        }
      }
    }
    set_field(result, "evidence", safe_evidence)
    if evidence_incomplete.val {
      set_field(result, "evidenceTruncated", Json::boolean(true))
    }
    save_diagnostic(
      "bulk-observation",
      mode,
      tunnel_directory=required(state, "tunnelDirectory"),
      evidence=result,
      evidence_incomplete=evidence_incomplete.val,
      evidence_stable_activity=true,
      protected_secrets=secrets,
      environment=workspace_environment(state),
      recording=operation_recording(state),
    )
    if mode == "status" {
      set_field(result, "outcome", Json::string("observed"))
      save_diagnostic(
        "bulk-workspace",
        "observed",
        evidence=result,
        evidence_incomplete=evidence_incomplete.val,
        evidence_stable_activity=true,
        protected_secrets=secrets,
        environment=workspace_environment(state),
        recording=operation_recording(state),
      )
      return Some(result)
    }
    if mode == "stop" {
      if status == "Stopped" {
        set_field(result, "reason", Json::string("already_stopped"))
      } else if !options.force &&
        (
          status != "Running" ||
          field(evidence, "activity") != Some(Json::string("idle"))
        ) {
        set_field(result, "reason", Json::string("not_idle"))
      } else {
        let (scope, valid) = bulk_identity(state, options.provider)
        guard scope && valid else {
          raise AdapterError("Workspace changed before stop")
        }
        mutating = true
        pause_tunnel(state)
        defer unpause_tunnel(state)
        stop_workspace(state)
        set_field(result, "outcome", Json::string("success"))
      }
    } else if status == "Running" {
      set_field(result, "reason", Json::string("already_running"))
    } else if status != "Stopped" {
      set_field(result, "reason", Json::string("workspace_not_stopped"))
    } else {
      let (scope, valid) = bulk_identity(state, options.provider)
      guard scope && valid else {
        raise AdapterError("Workspace changed before resume")
      }
      mutating = true
      unpause_tunnel(state)
      ignore(
        devsy(
          state,
          [
            "--result-format", "json", "workspace", "up", "--id", id, "--ide-launch",
            "skip",
          ] +
          orca_storage_args(state),
          "workspace-resume",
        ),
      )
      set_field(result, "outcome", Json::string("success"))
      idle_reset(state, "workspace_resumed")
    }
  } catch {
    error => {
      set_field(
        result,
        "outcome",
        Json::string(if mutating { "failed" } else { "skipped" }),
      )
      let detail = workspace_error_detail(state, error)
      set_field(result, "evidence", unknown_activity(detail))
      set_field(result, "error", Json::string(detail))
    }
  }
  if mode == "resume" &&
    field(result, "outcome") == Some(Json::string("success")) {
    recover_connection(state) catch {
      error => {
        set_field(result, "outcome", Json::string("failed"))
        set_field(
          result,
          "error",
          Json::string(workspace_error_detail(state, error)),
        )
      }
    }
  }
  save_diagnostic(
    "bulk-workspace",
    mode,
    evidence=result,
    evidence_incomplete=field(result, "evidenceTruncated") ==
      Some(Json::boolean(true)),
    evidence_stable_activity=true,
    protected_secrets=secrets,
    environment=workspace_environment(state),
    recording=operation_recording(state),
  )
  Some(result)
}

///|
pub async fn bulk(mode : String, args : Array[String]) -> Unit {
  defer @async.protect_from_cancel(async fn() { finish_diagnostic_recording() })
  let mut failure_recorded = false

///|
fn codex_timestamp(milliseconds : UInt64) -> String raise {
  let utc = @time.PlainDateTime::from_unix_second(
    (milliseconds / 1000).reinterpret_as_int64(),
    0,
    @time.utc_offset,
  )
  let fraction = (milliseconds % 1000).to_string()
  utc.to_string() + "." + "0".repeat(3 - fraction.length()) + fraction + "Z"
}

///|
async fn codex_addon(state : Json) -> Unit {
  if field(state, "codexAuth") != Some(Json::boolean(true)) {
    return
  }
  let started = @env.now()
  progress_message("codex-auth: running…")
  let mut stage = "read"
  try {
    @async.with_timeout(45000, async fn() {
      let home = @env.get_env_var("CODEX_HOME").unwrap_or(
        environment("HOME") + "/.codex",
      )
      guard @fs.file_size(home + "/auth.json") <= 65536L else {
        raise AdapterError("Invalid Codex auth size")
      }
      stage = "refresh"
      let auth = codex_credentials(home, recording=operation_recording(state))
      let access = auth.access
      let payload : Json = {
        "auth_mode": "chatgptAuthTokens",
        "tokens": {
          "id_token": access,
          "access_token": access,
          "refresh_token": "",
          "account_id": auth.account,
        },
        "last_refresh": codex_timestamp(@env.now()),
      }
      let script =
        #|set -eu
        #|home="${CODEX_HOME:-$HOME/.codex}"
        #|test -z "${OPENAI_API_KEY:-}${CODEX_ACCESS_TOKEN:-}" || { printf '%s\n' 'Existing API credentials prevent Codex auth delivery' >&2; exit 1; }
        #|if test -f "$home/config.toml"; then
        #|  ! grep -Eq '^[[:space:]]*cli_auth_credentials_store[[:space:]]*=[[:space:]]*"(auto|keyring)"' "$home/config.toml" || { printf '%s\n' 'Codex credential store is not file based' >&2; exit 1; }
        #|fi
        #|umask 077
        #|mkdir -p "$home"
        #|test ! -L "$home/auth.json" || { printf '%s\n' 'Codex auth file is a symbolic link' >&2; exit 1; }
        #|if test -f "$home/auth.json"; then
        #|  test -f "$home/.orca-env-devsy-auth" || { printf '%s\n' 'Existing Codex auth is not managed by this adapter' >&2; exit 1; }
        #|  test "$(sha256sum < "$home/auth.json")" = "$(cat "$home/.orca-env-devsy-auth")" || { printf '%s\n' 'Existing Codex auth changed since delivery' >&2; exit 1; }
        #|fi
        #|temporary=$(mktemp "$home/auth.XXXXXX")
        #|trap 'rm -f "$temporary"' EXIT
        #|cat > "$temporary"
        #|mv "$temporary" "$home/auth.json"
        #|sha256sum < "$home/auth.json" > "$home/.orca-env-devsy-auth"
      stage = "deliver"
      let sink = @process.redirect_to_file("/dev/null", shared=true)
      defer sink.close()
      let (errors, stderr) = @process.read_from_process()
      defer errors.close()
      stage = "pipe"
      let (input, writer) = @process.write_to_process()
      defer writer.close()
      @async.with_task_group(async fn(group) {
        stage = "spawn"
        let process = @process.spawn(
          group,
          workspace_program(state, "ssh"),
          extra_env=workspace_environment(state),
          cwd?=workspace_directory(state).map(path => path[:]),
          inherit_env=false,
          mux_ssh_args(state) + [script],
          stdin=input,
          stdout=sink,
          stderr~,
        )
        let output = DiagnosticCapture::new(8192)
        group.spawn_bg(no_wait=true, async fn() { output.read(errors) })
        stage = "write"
        let write_error = try {
          writer.write(payload.stringify() + "\n")
          None
        } catch {
          error =>
            if @async.is_being_cancelled() {
              raise error
            } else {
              Some(error)
            }
        }
        writer.close()
        stage = "wait"
        let status = if write_error is Some(error) {
          @async.with_timeout(1000, async fn() { process.wait() }) catch {
            wait_error => {
              if @async.is_being_cancelled() {
                raise wait_error
              }
              raise AdapterError(
                "Codex auth input transfer failed; process exit unavailable: " +
                diagnostic_error(
                  error,
                  environment=workspace_environment(state),
                ),
              )
            }
          }
        } else {
          process.wait()
        }
        wait_diagnostic_captures([output])
        let stderr = output.output.to_bytes()
        let truncated = output.truncated || !output.finished
        let protected_values = workspace_output_secrets(state)
        if protected_values is None {
          suppress_workspace_recording(state)
        }
        let detail = if protected_values is Some(values) {
          diagnostic_output(
            stderr,
            workspace_environment(state),
            protected_input=payload.stringify(),
            protected_secrets=values,
            omitted=truncated,
          )
        } else {
          Some(
            "error detail unavailable because workspace protection values could not be read\n[error details incomplete or truncated]",
          )
        }
        guard status == 0 else {
          raise AdapterError(
            "Codex auth delivery failed (exit \{status})" +
            detail.map(value => ":\n" + value).unwrap_or("") +
            write_error
            .map(error => {
              "\nInput transfer failed: " +
              diagnostic_error(error, environment=workspace_environment(state))
            })
            .unwrap_or(""),
          )
        }
        if write_error is Some(error) {
          raise error
        }
        if truncated {
          save_diagnostic(
            "codex-auth",
            "stderr-incomplete",
            phase="deliver",
            error_type="capture_incomplete",
            error_message=detail.unwrap_or(
              "Codex auth stderr was not fully captured",
            ),
            details_truncated=true,
            recording=operation_recording(state),
          )
        }
      })
    })
    save_diagnostic(
      "codex-auth",
      "success",
      recording=operation_recording(state),
    )
    progress_message("codex-auth: done (" + progress_timing(started) + ")")
  } catch {
    error => {
      progress_message(
        "warning: Codex authentication addon failed at " +
        stage +
        "; continuing (" +
        progress_timing(started) +
        ")",
      )
      let detail = workspace_error_detail(state, error)
      save_diagnostic(
        "codex-auth",
        "warning",
        phase=stage,
        error_type=if error is @async.TimeoutError {
          "timeout"
        } else {
          "auth_failed"
        },
        error_message=detail,
        recording=operation_recording(state),
      )
    }
  }
}

///|
priv struct CodexAuth {
  access : String
  account : String
  expiry : Double
  secrets : Array[String]
}

///|
async fn read_codex_auth(home : String) -> CodexAuth {
  guard @fs.file_size(home + "/auth.json") <= 65536L else {
    raise AdapterError("Invalid Codex auth size")
  }
  let source = @fs.read_file(home + "/auth.json")
  guard source.binary().length() <= 65536 else {
    raise AdapterError("Invalid Codex auth size")
  }
  let auth = @json.parse(source.text())
  guard (
      field(auth, "OPENAI_API_KEY") == None ||
      field(auth, "OPENAI_API_KEY") == Some(Json::null())
    ) &&
    (
      field(auth, "auth_mode") == None ||
      field(auth, "auth_mode") == Some(Json::string("chatgpt"))
    ) else {
    raise AdapterError("Unsupported Codex auth mode")
  }
  guard field(auth, "tokens") is Some(tokens) else {
    raise AdapterError("Missing Codex auth tokens")
  }
  let access = required(tokens, "access_token")
  let secrets = [access]
  for name in ["id_token", "refresh_token"] {
  for name in ["id_token", "refresh_token"] {
    if field(tokens, name) is Some(Json::String(value)) && value != "" {
      secrets.push(value)
    }
  }
  let segments = access.split(".").to_array()
  guard segments.length() == 3 else {
    raise AdapterError("Invalid access token")
  }
  let encoded = segments[1]
    .to_owned()
    .replace_all(old="-", new="+")
    .replace_all(old="_", new="/")
  let padding = (4 - encoded.length() % 4) % 4
  let claims = @json.parse(
    @utf8.decode(@base64.decode(encoded + "=".repeat(padding))),
  )
  guard field(claims, "exp") is Some(Json::Number(expiry, ..)) else {
    raise AdapterError("Invalid access token expiry")
  }
  { access, account: required(tokens, "account_id"), expiry, secrets, }
}

///|
async fn codex_rpc_response(
  reader : @process.ReadFromProcess,
  id : Int32,
  secrets : Array[String],
) -> Unit {
  let bytes : Array[Byte] = []
  let mut total = 0
  while true {
    let byte = reader.read_exactly(1)[0]
    total += 1
    guard total <= 1048576 else {
      raise AdapterError("Codex refresh output limit")
    }
    if byte == b'\n' {
      let response = @json.parse(@utf8.decode(Bytes::from_array(bytes)))
      bytes.clear()
      if field(response, "id") == Some(Json::number(id.to_double())) {
        if field(response, "error") is Some(error) {
          let code = match field(error, "code") {
            Some(Json::Number(value, ..)) => " code " + value.to_string()
            _ => ""
          }
          let message = match field(error, "message") {
            Some(Json::String(value)) =>
              ": " + diagnostic_text(value, protected_secrets=secrets)
            _ => ""
          }
          raise AdapterError("Codex refresh RPC \{id} failed" + code + message)
        }
        guard field(response, "result") != None else {
          raise AdapterError("Codex refresh RPC \{id} returned no result")
        }
        return
      }
    } else {
      bytes.push(byte)
    }
  }
}

///|
async fn refresh_codex(home : String, secrets : Array[String]) -> Unit {
  let (reader, output) = @process.read_from_process()
  defer reader.close()
  let (input, writer) = @process.write_to_process()
  defer writer.close()
  let (errors, stderr) = @process.read_from_process()
  defer errors.close()
  let captured = @buffer.Buffer(size_hint=1024)
  let incomplete : Ref[Bool] = { val: false, }
  let finished : Ref[Bool] = { val: false, }
  let failure = try {
    @async.with_task_group(async fn(group) {
      ignore(
        @process.spawn(
          group,
          "codex",
          ["app-server", "--stdio"],
          extra_env={ "CODEX_HOME": home },
          stdin=input,
          stdout=output,
          stderr~,
          no_wait=true,
        ),
      )
      group.spawn_bg(no_wait=true, async fn() {
        while errors.read_some(max_len=4096) is Some(chunk) {
          let remaining = 8192 - captured.length()
          let count = if chunk.length() < remaining {
            chunk.length()
          } else {
            remaining
          }
          if count > 0 {
            captured.write_bytes(chunk[:count])
          }
          if count < chunk.length() {
            incomplete.val = true
          }
        }
        finished.val = true
      })
      let initialize : Json = {
        "id": 1,
        "method": "initialize",
        "params": {
          "clientInfo": { "name": "orca-env-devsy", "version": version },
        },
      }
      writer.write(initialize.stringify() + "\n")
      codex_rpc_response(reader, 1, secrets)
      writer.write("{\"method\":\"initialized\"}\n")
      writer.write(
        "{\"id\":2,\"method\":\"account/read\",\"params\":{\"refreshToken\":true}}\n",
      )
      codex_rpc_response(reader, 2, secrets)
    })
    None
  } catch {
    error => Some(error)
  }
  if failure is Some(error) {
    if @async.is_being_cancelled() {
      raise error
    }
    let protected_input : Json = { "access_token": secrets }
    let detail = diagnostic_output(
      captured.to_bytes(),
      @env.get_env_vars(),
      protected_input=protected_input.stringify(),
      omitted=incomplete.val || !finished.val,
    )
    raise AdapterError(
      diagnostic_error(error) +
      detail
      .map(value => "\nCodex app-server stderr: " + value)
      .unwrap_or(
        if finished.val {
          ""
        } else {
          "\n[Codex app-server stderr incomplete]"
        },
      ),
    )
  }
}

///|
async fn codex_credentials(home : String, recording~ : Bool) -> CodexAuth {
  let initial = read_codex_auth(home)
  if initial.expiry - @env.now().to_double() / 1000 >= 604800 {
    return initial
  }
  let lock = @fs.open(
    home + "/.orca-env-devsy-refresh.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  while !lock.try_lock(Exclusive) {
    @async.sleep(100)
  }
  let before = read_codex_auth(home)
  if before.expiry - @env.now().to_double() / 1000 >= 604800 {
    return before
  }
  let mut phase = "refresh"
  try {
    refresh_codex(home, before.secrets)
    phase = "verify"
    let after = read_codex_auth(home)
    guard after.access != before.access && after.expiry > before.expiry else {
      raise AdapterError("Codex refresh not persisted")
    }
    save_diagnostic("codex-refresh", "success", recording~)
  } catch {
    error => {
      progress_write(
        "orca-env-devsy: warning: Codex refresh failed; checking remaining token lifetime\n",
      )
      let detail = diagnostic_error(error)
      save_diagnostic(
        "codex-refresh",
        "warning",
        phase~,
        error_type=if error is @async.TimeoutError {
          "timeout"
        } else {
          "refresh_failed"
        },
        error_message=detail,
        recording~,
      )
    }
  }
  let current = read_codex_auth(home)

///|
priv suberror SettingsProcessError {
  SettingsProcessError(String, String, Int32, String?)
}

///|
#borrow(buffer)
extern "C" fn process_executable(
  pid : Int32,
  buffer : Bytes,
  capacity : Int32,
) -> Int32 = "orca_process_executable"

///|
async fn settings_executable(pid : Int32) -> String {
  if @async.platform is Linux {
    return @fs.realpath("/proc/\{pid}/exe")
  }
  let buffer = Bytes::make(4096, 0)
  let length = process_executable(pid, buffer, buffer.length())
  guard length > 0 && length < buffer.length() else {
    raise AdapterError("Cannot locate the running host Orca executable")
  }
  @utf8.decode(buffer[:length])
}

///|
fn settings_parent(path : String) -> String {
  let parts = path.split("/").to_array()
  parts[:parts.length() - 1].join("/")
}

///|
async fn host_orca_location() -> (String, String, String) {
  let home = environment("HOME")
  let user_data = @env.get_env_var("ORCA_USER_DATA_PATH")
    .filter(p => p != "")
    .unwrap_or(
      if @async.platform is MacOS {
        home + "/Library/Application Support/orca"
      } else {
        @env.get_env_var("XDG_CONFIG_HOME")
        .filter(p => p != "")
        .unwrap_or(home + "/.config") +
        "/orca"
      },
    )
  let metadata = @json.parse(
    @fs.read_file(user_data + "/orca-runtime.json").text(),
  )
  let pid = match field(metadata, "pid") {
    Some(Json::Number(value, ..)) if value > 1 && value == value.trunc() =>
      value.to_int()
    _ => raise AdapterError("Invalid host Orca runtime PID")
  }
  let executables = [settings_executable(pid)]
  if @async.platform is Linux {
    let args = @fs.read_file("/proc/\{pid}/cmdline")
      .text()
      .split("\u0000")
      .to_array()
    for i = 0; i + 1 < args.length(); i = i + 1 {
      if args[i] == "--spawner-exec-path" {
        executables.push(args[i + 1].to_owned())
      }
    }
  }
  for executable in executables {
    let parent = settings_parent(executable)
    for
      resources in [
        parent + "/resources",
        settings_parent(parent) + "/Resources",
      ] {
      if @fs.exists(
          resources +
          "/app.asar.unpacked/out/main/persistence/profile-state/profile-state-domain-reader.js",
        ) {
        return (executable, resources, user_data)
      }
    }
  }
  raise AdapterError("Cannot locate the running host Orca resources")
}

///|
async fn host_orca_settings() -> String {
  let (executable, resources, user_data) = host_orca_location()
  let env = @env.get_env_vars()
  env.set("ELECTRON_RUN_AS_NODE", "1")
  env.remove("NODE_OPTIONS")
  env.remove("NODE_REPL_EXTERNAL_MODULE")
  settings_process(
    executable,
    ["-e", orca_settings_script(), "--", "export", resources, user_data],
    environment=env,
  )
}

///|
async fn settings_process(
  program : String,
  args : Array[String],
  environment~ : Map[String, String],
  input? : String,
  protected_secrets? : Array[String],
  protection_incomplete~ : Bool = false,
) -> String {
  let (stdin, writer) = @process.write_to_process()
  defer writer.close()
  @async.with_task_group(async fn(group) {
    let output = group.spawn(async fn() {
      diagnostic_process_output(
        program,
        args,
        environment~,
        stdin~,
        stdout_limit=4194304,
        stderr_limit=8192,
      )
    })
    let write_error = try {
      if input is Some(value) {
        writer.write(value)
      }
      None
    } catch {
      error =>
        if @async.is_being_cancelled() {
          raise error
        } else {
          Some(error)
        }
    }
    writer.close()
    let (status, stdout, stdout_truncated, stderr, stderr_truncated) = if write_error
      is Some(error) {
      @async.with_timeout(1000, async fn() { output.wait() }) catch {
        wait_error => {
          if @async.is_being_cancelled() {
            raise wait_error
          }
          raise AdapterError(
            "Orca settings input transfer failed; process exit unavailable: " +
            diagnostic_error(error, environment~),
          )
        }
      }
    } else {
      output.wait()
    }
    guard status == 0 else {
      let mut phase = "process"
      let mut code = "process_exit"
      let mut detail = if protection_incomplete {
        Some(
          "error detail unavailable because workspace protection values could not be read\n[error details incomplete or truncated]",
        )
      } else {
        diagnostic_output(
          stderr,
          environment,
          protected_input?=input,
          protect_all_input=true,
          protected_secrets?,
          omitted=stderr_truncated,
        )
      }
      if !stderr_truncated && !protection_incomplete {
        try {
          let error = @json.parse(@utf8.decode(stderr))
          let reported_phase = required(error, "phase")
          let reported_code = required(error, "code")
          if [
              "load", "read", "normalize", "input", "profile", "write", "verify",
            ].contains(reported_phase) &&
            ["EACCES", "ENOENT", "EBUSY", "ENOSPC", "INCOMPATIBLE", "INVALID"].contains(
              reported_code,
            ) {
            phase = reported_phase
            code = reported_code
            let kind = match field(error, "kind") {
              Some(Json::String(value)) if [
                  "Error", "TypeError", "SyntaxError", "ReferenceError", "RangeError",
                  "AssertionError", "URIError",
                ].contains(value) => Some(value)
              _ => None
            }
            let native_code = match field(error, "nativeCode") {
              Some(Json::String(value)) if value.length() > 0 &&
                value.length() <= 64 &&
                value
                .iter()
                .all(c => {
                  (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
                }) => Some(value)
              _ => None
            }
            detail = if kind is Some(kind) {
              Some(
                kind +
                native_code.map(value => " (" + value + ")").unwrap_or(""),
              )
            } else {
              None
            }
            for
              name in (if native_code == Some("MODULE_NOT_FOUND") {
                ["target", "missing", "cause", "location", "message", "path"]
              } else {
                ["target", "cause", "location", "message", "path"]
              }) {
              if field(error, name) is Some(Json::String(value)) &&
                value.length() > 0 &&
                value.length() <= 1024 &&
                diagnostic_output(
                  @utf8.encode(value),
                  environment,
                  protected_input?=input,
                  protect_all_input=true,
                  protected_secrets?,
                  omitted=field(error, "detailsTruncated") ==
                    Some(Json::boolean(true)) &&
                    (name == "message" || name == "path" || name == "missing"),
                )
                is Some(safe) {
                detail = Some(
                  detail.unwrap_or("Error") + " " + name + "=" + safe,
                )
              }
            }
            if field(error, "detailsTruncated") == Some(Json::boolean(true)) {
              detail = Some(
                detail.unwrap_or("Error") +
                "\n[error details incomplete or truncated]",
              )
            }
          }
        } catch {
          _ => ()
        }
      }
      if write_error is Some(error) {
        detail = Some(
          detail.unwrap_or("Process exited without readable stderr") +
          "\nInput transfer failed: " +
          diagnostic_error(error, environment~),
        )
      }
      if stdout_truncated {
        detail = Some(incomplete_diagnostic_detail(detail))
      }
      raise SettingsProcessError(phase, code, status, detail)
    }
    if write_error is Some(error) {
      raise error
    }
    guard !stdout_truncated else {
      raise AdapterError("Orca settings result exceeds size limit")
    }
    @utf8.decode(stdout)
  })
}

