///|
async fn git_forwarding_enabled(state : Json) -> Bool {
  let options = @json.parse(
    devsy(
      state,
      ["--result-format", "json", "context", "get"],
      "git-relay-options",
    ),
  )
  let option = field(options, "SSH_INJECT_GIT_CREDENTIALS").unwrap_or(
    Json::null(),
  )
  match field(option, "value") {
    Some(Json::String("false")) => false
    Some(Json::String("true")) => true
    _ => field(option, "default") != Some(Json::string("false"))
  }
}

///|
priv enum RelayReadiness {
  Ready
  WaitingForGitHelper
  Retry(String)
  Unsupported
}

///|
async fn relay_readiness(
  state : Json,
  directory : String,
  git_enabled : Bool,
  record_success~ : Bool,
) -> RelayReadiness {
  let script =
    #|# orca-relay-readiness
    #|set -eu
    #|curl --disable --noproxy '*' --silent --max-time 1 --max-filesize 4096 --write-out '\n%{http_code}' http://localhost:12049/ready
  let started = @env.now()
  let environment = workspace_environment(state)
  let pairing = if state_recording(state) {
    workspace_pairing_secrets(state)
  } else {
    Some([])
  }
  if pairing is None {
    suppress_workspace_recording(state)
  }
  let pairing_secrets = pairing.unwrap_or([])
  let evidence : Json = { "gitEnabled": git_enabled }
  let mut phase = "readiness"
  let mut exit_code = None
  let mut error_detail = None
  let mut cancelled = false
  let result = @async.with_timeout(3000, async fn() {
    let (code, output, output_truncated, stderr, stderr_truncated) = diagnostic_process_output(
      workspace_program(state, "ssh"),
      ssh_mux_options(state, directory) + [script],
      environment~,
      cwd?=workspace_directory(state).map(path => path[:]),
      stdout_limit=8192,
      stderr_limit=8192,
    )
    exit_code = Some(code)
    if code != 0 {
      error_detail = diagnostic_output(
        stderr,
        environment,
        protected_secrets=pairing_secrets,
        omitted=stderr_truncated,
      )
      if output_truncated {
        error_detail = Some(incomplete_diagnostic_detail(error_detail))
      }
      return RelayReadiness::Retry(
        if code == 28 {
          "http_timeout"
        } else {
          "transport_error"
        },
      )
    }
    if output_truncated {
      error_detail = Some(
        "Readiness response exceeds the capture limit\n[error details incomplete or truncated]",
      )
      return RelayReadiness::Retry("response_too_large")
    }
    let text = @utf8.decode(output).trim().to_owned()
    let lines = text.split("\n").to_array()
    let status = lines.last().unwrap_or("").to_owned()
    if status.length() == 3 && status.iter().all(c => c >= '0' && c <= '9') {
      set_field(evidence, "httpStatus", Json::string(status))
    }
    if status == "404" {
      return RelayReadiness::Unsupported
    }
    if status != "200" {
      return RelayReadiness::Retry(
        if status == "503" {
          "http_503"
        } else {
          "http_error"
        },
      )
    }
    let body = text[:text.length() - status.length()]
      .to_owned()
      .trim()
      .to_owned()
    phase = "response"
    let value = @json.parse(body) catch {
      error => {
        error_detail = Some(diagnostic_error(error, environment~))
        return RelayReadiness::Retry("schema_invalid")
      }
    }
    if field(value, "version") != Some(Json::number(1)) {
      return RelayReadiness::Unsupported
    }
    if field(value, "owner") != field(state, "user") {
      let progress = Progress::new("relay-probe", environment~)
      for (name, source) in [("expectedOwner", state), ("observedOwner", value)] {
        let key = if name == "expectedOwner" { "user" } else { "owner" }
        if field(source, key) is Some(Json::String(owner)) {
          set_field(
            evidence,
            name,
            Json::string(
              progress.safe_message(owner).unwrap_or("[unavailable]"),
            ),
          )
        }
      }
      return RelayReadiness::Retry("owner_mismatch")
    }
    for name in ["host_owner", "instance"] {
      if field(value, name) is Some(Json::String(value)) && value != "" {
        continue
      }
      set_field(evidence, "invalidField", Json::string(name))
      return RelayReadiness::Retry("schema_invalid")
      return RelayReadiness::Retry("schema_invalid")
    }
    if git_enabled {
      phase = "git-helper"
      let helper = "git config --global --get credential.helper | grep -F 'internal agent git-credentials' >/dev/null"
      let (code, _, output_truncated, stderr, stderr_truncated) = diagnostic_process_output(
        workspace_program(state, "ssh"),
        ssh_mux_options(state, directory) + [helper],
        environment~,
        cwd?=workspace_directory(state).map(path => path[:]),
        stdout_limit=0,
        stderr_limit=8192,
      )
      exit_code = Some(code)
      if code == 1 {
        error_detail = diagnostic_output(
          stderr,
          environment,
          protected_secrets=pairing_secrets,
          omitted=stderr_truncated,
        )
        if output_truncated {
          error_detail = Some(incomplete_diagnostic_detail(error_detail))
        }
        return RelayReadiness::WaitingForGitHelper
      }
      if code != 0 {
        error_detail = diagnostic_output(
          stderr,
          environment,
          protected_secrets=pairing_secrets,
          omitted=stderr_truncated,
        )
        if output_truncated {
          error_detail = Some(incomplete_diagnostic_detail(error_detail))
        }
        return RelayReadiness::Retry("transport_error")
      }
    }
    RelayReadiness::Ready
  }) catch {
    @async.TimeoutError => RelayReadiness::Retry("ssh_timeout")
    error => {
      cancelled = @async.is_being_cancelled()
      error_detail = Some(diagnostic_error(error, environment~))
      RelayReadiness::Retry("transport_error")
    }
  }
  match result {
    Ready =>
      if record_success {
        save_diagnostic(
          "relay-probe",
          "success",
          phase~,
          duration_ms=(@env.now() - started).to_double(),
          evidence~,
          tunnel_directory=directory,
          environment~,
          protected_secrets=pairing_secrets,
          recording=state_recording(state),
        )
      }
    WaitingForGitHelper =>
      save_diagnostic(
        "relay-probe",
        "pending",
        error_type="git_helper_unavailable",
        phase~,
        exit_code?,
        error_message?=error_detail,
        evidence~,
        duration_ms=(@env.now() - started).to_double(),
        tunnel_directory=directory,
        environment~,
        protected_secrets=pairing_secrets,
        recording=state_recording(state),
      )
    Retry(reason) =>
      save_diagnostic(
        "relay-probe",
        if cancelled {
          "cancelled"
        } else {
          "failed"
        },
        error_type=if cancelled { "cancelled" } else { reason },
        phase~,
        exit_code?,
        error_message?=error_detail,
        timeout_ms?=if reason == "ssh_timeout" { Some(3000) } else { None },

