      @fs.mkdir(base + "/" + name, recursive=true)
      let receipt : Json = { "pid": "1" }
      if name != "unknown" {
        set_field(receipt, "recording", Json::boolean(name == "enabled"))
      }
      @fs.write_file(base + "/" + name + "/state.json", receipt.stringify())
    }
    if mode == "running" {
      @async.with_timeout(10000, async fn() {
        @async.with_task_group(async fn(group) {
          let sink = @process.redirect_to_file("/dev/null", shared=true)
          defer sink.close()
          let child = @process.spawn(
