        })
      })
    } else {
      let (status, _, _) = invoke("restart", env, directory)
      assert_true(status != 0)
      for name in ["enabled", "disabled", "unknown"] {
        @fs.write_file(base + "/" + name + "/done", "")
      }
    }
    let failures = fixture_events(directory).filter(event => {
      field(event, "errorType") ==
      Some(Json::string("transport_cleanup_failed"))
    })
    assert_true(failures.length() > 0)
    for event in failures {
      assert_eq(
        field(field(event, "evidence").unwrap(), "transport"),
        Some(Json::string(base + "/enabled")),
      )
    }
  }
}

