    let child = @process.spawn(
      group,
      integration_binary(),
      [
        "--supervisor",
        env.get("XDG_STATE_HOME").unwrap() + "/orca-env-devsy",
        worker,
      ],
      extra_env=env,
      stdout=sink,
      stderr~,
    )
    group.spawn_bg(no_wait=true, async fn() {
      while reader.read_some(max_len=4096) is Some(chunk) {
        let text = @utf8.decode_lossy(chunk)
        if captured.val.length() + text.length() > 8192 {
          capture_incomplete.val = true
        } else {
          captured.val += text
        }
      }
    })
    defer (@fs.remove(worker + "/enabled") catch { _ => () })
    let failure = try {
      idle_wait_for(async fn() {
        @fs.exists(directory + "/initial-probe-started")
      })
      @fs.write_file(directory + "/fail-next-check", "")
      @fs.write_file(worker + "/probe-request", "")
      @fs.write_file(directory + "/release-initial-probe", "")
      @async.with_timeout(
        5000,
        async fn() {
          while !@fs.exists(directory + "/master-recreated") &&
                !@fs.exists(directory + "/master-conflict") {
            @async.sleep(10)
          }
        },
        error=AdapterError("Timed out waiting for primary replacement"),
      )
      assert_false(@fs.exists(directory + "/master-conflict"))
      assert_true(@fs.exists(directory + "/master-recreated"))
      idle_wait_for(async fn() {
        fixture_events(directory)
        .iter()
        .any(event => {
          field(event, "stage") == Some(Json::string("relay-probe")) &&
          field(event, "exitCode") == Some(Json::number(79))
        })
      })
      let probe_failures = fixture_events(directory).filter(event => {
        field(event, "stage") == Some(Json::string("relay-probe")) &&
        field(event, "exitCode") == Some(Json::number(79))
      })
      assert_true(probe_failures.length() > 0)
      let probe = probe_failures[probe_failures.length() - 1]
      assert_eq(field(probe, "phase"), Some(Json::string("readiness")))
      let detail = required(probe, "errorMessage")
      assert_true(
        detail.contains("readiness transport unavailable"),
        msg=detail,
      )
      assert_false(detail.contains("fixture-relay-secret"), msg=detail)
      assert_false(detail.contains("fixture-readiness-pairing"), msg=detail)
      assert_true(detail.contains("[redacted]"), msg=detail)
      @fs.remove(worker + "/enabled")
      assert_eq(
        @async.with_timeout(
          5000,
          async fn() { child.wait() },
          error=AdapterError(
            "Timed out waiting for recovery supervisor shutdown",
          ),
        ),
        0,
      )
      None
    } catch {
      error => Some(error)
    }
    if failure is Some(error) {
      let redaction_env = @env.get_env_vars()
      for name, value in env {
        redaction_env.set(name, value)
      }
      let state = @fs.read_file(worker + "/status.json").text() catch {
        state_error => diagnostic_error(state_error, environment=redaction_env)
      }
      let markers = []
      for name in ["fail-next-check", "master-recreated", "master-conflict"] {
        markers.push(
          name + "=" + @fs.exists(directory + "/" + name).to_string(),
        )
      }
      for name in ["enabled", "probe-request", "worker-error.json"] {
        markers.push(name + "=" + @fs.exists(worker + "/" + name).to_string())
      }
      let stderr_incomplete = capture_incomplete.val || child.try_wait() is None
      fail(
        diagnostic_error(error, environment=redaction_env) +
        "\n" +
        markers.join(" ") +
        "\nstatus: " +
        redact_credentials(state) +
        "\nsupervisor stderr: " +
        diagnostic_text(
          captured.val,
          environment=redaction_env,
          omitted=stderr_incomplete,
        ) +
        "\n" +
        fixture_failure_events(directory),
      )
    }
  })
}

